#!/usr/bin/env python3
"""Analyze the planar-dual graph generated by U-U edges.

Input is the output of `grid_graphs fullub-pattern M N`, or just a raw block of
rows using `U` for non-full vertices and `.` for full vertices. The script
constructs the dual graph whose vertices are the grid cells plus the exterior
face. Each U-U primal edge contributes the corresponding dual edge. The
forced-edge graph is a forest exactly when this dual graph connects every cell
to the exterior.
"""

from __future__ import annotations

import argparse
import sys
from collections import Counter, defaultdict, deque


Face = tuple[int, int] | str


def q_formula(n: int) -> int:
    k, r = divmod(n, 3)
    if r == 0:
        return 6 * k * k - 3 * k + 2
    if r == 1:
        return 6 * k * k + k + 1
    return 6 * k * k + 5 * k + 3


def parse_pattern(text: str) -> list[str]:
    lines = [line.rstrip() for line in text.splitlines()]
    in_u = False
    rows: list[str] = []
    for line in lines:
        if line.startswith("# U/non-full pattern"):
            in_u = True
            continue
        if in_u:
            if line.startswith("#"):
                break
            if line and set(line) <= {"U", "."}:
                rows.append(line)
    if rows:
        return rows
    rows = [line for line in lines if line and set(line) <= {"U", "."}]
    if not rows:
        raise SystemExit("no U-pattern rows found on stdin")
    return rows


class DSU:
    def __init__(self, items: list[Face]):
        self.parent = {x: x for x in items}

    def find(self, x: Face) -> Face:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: Face, b: Face) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        self.parent[rb] = ra
        return True


def dual_edge_for_horizontal(n: int, r: int, c: int) -> tuple[Face, Face]:
    # Primal edge (r,c)--(r,c+1).
    if r == 0:
        return "OUT", (0, c)
    if r == n - 1:
        return "OUT", (n - 2, c)
    return (r - 1, c), (r, c)


def dual_edge_for_vertical(n: int, r: int, c: int) -> tuple[Face, Face]:
    # Primal edge (r,c)--(r+1,c).
    if c == 0:
        return "OUT", (r, 0)
    if c == n - 1:
        return "OUT", (r, n - 2)
    return (r, c - 1), (r, c)


def analyze(rows: list[str]) -> None:
    n = len(rows)
    if any(len(row) != n for row in rows):
        raise SystemExit("only square patterns are supported")
    u = [[ch == "U" for ch in row] for row in rows]
    u_count = sum(sum(row) for row in u)
    q = q_formula(n)

    faces: list[Face] = ["OUT"] + [(r, c) for r in range(n - 1) for c in range(n - 1)]
    dsu = DSU(faces)
    adj: dict[Face, set[Face]] = defaultdict(set)
    dual_edges: list[tuple[Face, Face, str, tuple[int, int]]] = []

    row_u = [sum(row) for row in u]
    col_u = [sum(u[r][c] for r in range(n)) for c in range(n)]
    strip_u = Counter(r // 3 for r in range(n) for c in range(n) if u[r][c])
    mod_u = Counter((r % 3, c % 3) for r in range(n) for c in range(n) if u[r][c])

    for r in range(n):
        for c in range(n - 1):
            if u[r][c] and u[r][c + 1]:
                a, b = dual_edge_for_horizontal(n, r, c)
                dual_edges.append((a, b, "H", (r, c)))
                dsu.union(a, b)
                adj[a].add(b)
                adj[b].add(a)
    for r in range(n - 1):
        for c in range(n):
            if u[r][c] and u[r + 1][c]:
                a, b = dual_edge_for_vertical(n, r, c)
                dual_edges.append((a, b, "V", (r, c)))
                dsu.union(a, b)
                adj[a].add(b)
                adj[b].add(a)

    root = dsu.find("OUT")
    connected_faces = sum(1 for f in faces if dsu.find(f) == root)
    all_connected = connected_faces == len(faces)

    seen = {"OUT"}
    queue = deque(["OUT"])
    while queue:
        x = queue.popleft()
        for y in adj[x]:
            if y not in seen:
                seen.add(y)
                queue.append(y)

    print(f"n={n}")
    print(f"|U|={u_count} conjectured_q={q} match={u_count == q}")
    print(f"dual_vertices={len(faces)} dual_edges={len(dual_edges)}")
    print(f"faces_connected_to_out={connected_faces}/{len(faces)} all_connected={all_connected}")
    print("row_U=" + ",".join(map(str, row_u)))
    print("col_U=" + ",".join(map(str, col_u)))
    print("strip3_U=" + ",".join(f"{k}:{strip_u[k]}" for k in sorted(strip_u)))
    print("mod3_U=")
    for rr in range(3):
        print("  " + ",".join(str(mod_u[(rr, cc)]) for cc in range(3)))


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.parse_args()
    analyze(parse_pattern(sys.stdin.read()))


if __name__ == "__main__":
    main()
